-- AssetFlow demo data
--
-- Run Database-Initialize.sql first, then run this file in the same database.
-- UUID columns are generated by PostgreSQL. The short business keys in this
-- file are used to resolve relationships and are easier to read in pgAdmin.
--
-- Demo login:
--   Email:    admin@assetflow.test
--   Password: password
--
-- This is development data only. Change or remove the demo credentials before
-- using the database outside a local development environment.

BEGIN;

SET LOCAL search_path TO public;
SET CONSTRAINTS ALL DEFERRED;

DO $$
BEGIN
    IF to_regclass('public.departments') IS NULL THEN
        RAISE EXCEPTION 'AssetFlow schema is missing. Run Database-Initialize.sql first.';
    END IF;
END
$$;

-- ============================================================================
-- Departments and employees
-- ============================================================================

INSERT INTO departments (code, name, description)
