UPDATE departments
SET manager_employee_id = employee.id
FROM employees employee
WHERE departments.code = 'FIN'
  AND employee.employee_number = 'EMP-0002';

UPDATE departments
SET manager_employee_id = employee.id
FROM employees employee
WHERE departments.code = 'OPS'
  AND employee.employee_number = 'EMP-0003';

