INSERT INTO roles (name, description)
VALUES
    ('SUPER_ADMIN', 'Full access to every AssetFlow module.'),
    ('ADMIN', 'Administrative access to operational modules.'),
    ('DEPARTMENT_HEAD', 'Access to assets and records for a department.'),
    ('USER', 'Basic authenticated workspace access.')
ON CONFLICT (name) DO UPDATE
SET description = EXCLUDED.description;

INSERT INTO permissions (code, description)
VALUES
    ('ASSET_READ', 'View assets and asset details.'),
    ('ASSET_WRITE', 'Create and update assets.'),
    ('EMPLOYEE_READ', 'View employees and departments.'),
    ('EMPLOYEE_WRITE', 'Create and update employees.'),
    ('REPORT_READ', 'View reports and dashboard metrics.'),
    ('SETTINGS_WRITE', 'Manage organization settings.'),
    ('USER_MANAGE', 'Manage application user accounts.'),
    ('MAINTENANCE_WRITE', 'Manage maintenance tickets.'),
    ('PROCUREMENT_WRITE', 'Manage purchase orders and invoices.'),
    ('LICENSE_WRITE', 'Manage software licenses.')
ON CONFLICT (code) DO UPDATE
SET description = EXCLUDED.description;

-- The hash below is BCrypt for the demo password: password
INSERT INTO app_users (
    employee_id, username, password_hash, status, last_login_at,
    created_at, updated_at
)
SELECT employee.id,
       seed.username,
       '$2a$12$WXeKyOJe1RnmcgWWECT6Beqvk9BzoUaMF0k4uZZ7XEQqQfORP1Kda',
       'ACTIVE', NULL, seed.created_at, now()
FROM (
    VALUES
        ('EMP-0001', 'asset.admin', TIMESTAMPTZ '2026-01-02 08:00:00+05:30'),
        ('EMP-0002', 'finance.admin', TIMESTAMPTZ '2026-01-03 08:00:00+05:30')
) AS seed(employee_number, username, created_at)
JOIN employees employee ON employee.employee_number = seed.employee_number
ON CONFLICT (username) DO UPDATE
SET employee_id = EXCLUDED.employee_id,
    password_hash = EXCLUDED.password_hash,
    status = EXCLUDED.status,
    updated_at = now();

INSERT INTO user_roles (user_id, role_id)
SELECT app_user.id, role.id
FROM app_users app_user
JOIN roles role ON role.name = 'SUPER_ADMIN'
WHERE app_user.username = 'asset.admin'
ON CONFLICT DO NOTHING;

INSERT INTO user_roles (user_id, role_id)
SELECT app_user.id, role.id
FROM app_users app_user
JOIN roles role ON role.name = 'ADMIN'
WHERE app_user.username = 'finance.admin'
ON CONFLICT DO NOTHING;

INSERT INTO role_permissions (role_id, permission_id)
SELECT role.id, permission.id
FROM (
    VALUES
        ('SUPER_ADMIN', 'ASSET_READ'),
        ('SUPER_ADMIN', 'ASSET_WRITE'),
        ('SUPER_ADMIN', 'EMPLOYEE_READ'),
        ('SUPER_ADMIN', 'EMPLOYEE_WRITE'),
        ('SUPER_ADMIN', 'REPORT_READ'),
        ('SUPER_ADMIN', 'SETTINGS_WRITE'),
        ('SUPER_ADMIN', 'USER_MANAGE'),
        ('SUPER_ADMIN', 'MAINTENANCE_WRITE'),
        ('SUPER_ADMIN', 'PROCUREMENT_WRITE'),
        ('SUPER_ADMIN', 'LICENSE_WRITE'),
        ('ADMIN', 'ASSET_READ'),
        ('ADMIN', 'ASSET_WRITE'),
        ('ADMIN', 'EMPLOYEE_READ'),
        ('ADMIN', 'EMPLOYEE_WRITE'),
        ('ADMIN', 'REPORT_READ'),
        ('ADMIN', 'MAINTENANCE_WRITE'),
        ('ADMIN', 'PROCUREMENT_WRITE'),
        ('ADMIN', 'LICENSE_WRITE'),
        ('DEPARTMENT_HEAD', 'ASSET_READ'),
        ('DEPARTMENT_HEAD', 'EMPLOYEE_READ'),
        ('DEPARTMENT_HEAD', 'REPORT_READ'),
        ('DEPARTMENT_HEAD', 'MAINTENANCE_WRITE'),
        ('DEPARTMENT_HEAD', 'PROCUREMENT_WRITE'),
        ('USER', 'ASSET_READ'),
        ('USER', 'REPORT_READ')
) AS mapping(role_name, permission_code)
JOIN roles role ON role.name = mapping.role_name
JOIN permissions permission ON permission.code = mapping.permission_code
ON CONFLICT DO NOTHING;

