INSERT INTO purchase_order_items (
    purchase_order_id, category_id, description, quantity, received_quantity, unit_cost
)
SELECT purchase_order.id, category.id, seed.description, seed.quantity, seed.received_quantity, seed.unit_cost
FROM (
    VALUES
        ('PO-2026-0001', 'Laptops', 'Dell Latitude 7440 laptop', 3, 3, 900.00::numeric),
        ('PO-2026-0001', 'Monitors', 'Dell UltraSharp 27-inch monitor', 3, 3, 275.00::numeric),
        ('PO-2026-0002', 'Network Equipment', 'Managed 24-port network switch', 2, 0, 600.00::numeric)
) AS seed(po_number, category_name, description, quantity, received_quantity, unit_cost)
JOIN purchase_orders purchase_order ON purchase_order.po_number = seed.po_number
JOIN asset_categories category ON category.name = seed.category_name
WHERE NOT EXISTS (
    SELECT 1
    FROM purchase_order_items item
    WHERE item.purchase_order_id = purchase_order.id
      AND item.description = seed.description
);

