INSERT INTO assignments (
    asset_id, employee_id, assigned_by_user_id, assigned_at,
    expected_return_date, returned_at, status, handover_notes
)
SELECT asset.id, employee.id, app_user.id, seed.assigned_at,
       seed.expected_return_date, seed.returned_at, seed.status, seed.handover_notes
FROM (
    VALUES
        ('AST-LAP-0001', 'EMP-0004', 'asset.admin', TIMESTAMPTZ '2026-02-01 09:00:00+05:30', DATE '2027-02-01', NULL::timestamptz, 'ACTIVE', 'Issued for systems engineering work.'),
        ('AST-LAP-0002', 'EMP-0005', 'finance.admin', TIMESTAMPTZ '2025-01-10 09:00:00+05:30', DATE '2025-03-10', TIMESTAMPTZ '2025-03-10 17:00:00+05:30', 'TRANSFERRED', 'Transferred during the finance equipment refresh.'),
        ('AST-LAP-0002', 'EMP-0003', 'asset.admin', TIMESTAMPTZ '2025-03-11 09:00:00+05:30', NULL::date, TIMESTAMPTZ '2025-12-01 17:00:00+05:30', 'RETURNED', 'Returned after the temporary operations assignment.'),
        ('AST-MON-0001', 'EMP-0002', 'asset.admin', TIMESTAMPTZ '2026-03-05 09:00:00+05:30', NULL::date, TIMESTAMPTZ '2026-04-01 17:00:00+05:30', 'RETURNED', 'Returned to shared technology inventory.')
) AS seed(asset_tag, employee_number, username, assigned_at, expected_return_date, returned_at, status, handover_notes)
JOIN assets asset ON asset.asset_tag = seed.asset_tag
JOIN employees employee ON employee.employee_number = seed.employee_number
JOIN app_users app_user ON app_user.username = seed.username
WHERE NOT EXISTS (
    SELECT 1
    FROM assignments existing
    WHERE existing.asset_id = asset.id
      AND existing.employee_id = employee.id
      AND existing.assigned_at = seed.assigned_at
);

-- ============================================================================
-- Warranty policies, claims, and maintenance
-- ============================================================================

INSERT INTO warranty_policies (
    asset_id, vendor_id, policy_number, start_date, end_date,
    coverage, status, is_current
)
SELECT asset.id, vendor.id, seed.policy_number, seed.start_date, seed.end_date,
       seed.coverage, seed.status, seed.is_current
FROM (
    VALUES
        ('AST-LAP-0001', 'VEN-TECH', 'W-TECH-2026-0001', DATE '2026-01-20', DATE '2027-01-20', 'Hardware replacement and onsite support.', 'ACTIVE', true),
        ('AST-NET-0001', 'VEN-NET', 'W-NET-2025-0001', DATE '2025-10-01', DATE '2026-09-05', 'Parts and repair coverage for network hardware.', 'EXPIRING', true),
        ('AST-LAP-0003', 'VEN-TECH', 'W-TECH-2022-0001', DATE '2022-04-12', DATE '2025-12-31', 'Limited hardware warranty.', 'EXPIRED', false)
) AS seed(asset_tag, vendor_code, policy_number, start_date, end_date, coverage, status, is_current)
JOIN assets asset ON asset.asset_tag = seed.asset_tag
JOIN vendors vendor ON vendor.vendor_code = seed.vendor_code
WHERE NOT EXISTS (
    SELECT 1
    FROM warranty_policies existing
    WHERE existing.policy_number = seed.policy_number
);

INSERT INTO warranty_claims (
    warranty_id, assigned_to_user_id, claim_number, opened_at,
    status, description, claimed_amount, provider_reference
)
SELECT warranty.id, app_user.id, seed.claim_number, seed.opened_at,
       seed.status, seed.description, seed.claimed_amount, seed.provider_reference
FROM (
    VALUES
        ('W-NET-2025-0001', 'finance.admin', 'CLM-2026-0001', TIMESTAMPTZ '2026-08-12 10:30:00+05:30', 'SUBMITTED', 'Cooling fan failure reported by the warehouse team.', 350.00::numeric, 'NETSEC-CASE-8842'),
        ('W-TECH-2022-0001', 'asset.admin', 'CLM-2025-0004', TIMESTAMPTZ '2025-12-15 10:30:00+05:30', 'RESOLVED', 'Retired laptop motherboard failure.', 100.00::numeric, 'TECH-CASE-7710')
) AS seed(policy_number, username, claim_number, opened_at, status, description, claimed_amount, provider_reference)
JOIN warranty_policies warranty ON warranty.policy_number = seed.policy_number
JOIN app_users app_user ON app_user.username = seed.username
ON CONFLICT (claim_number) DO NOTHING;

UPDATE warranty_claims
SET resolved_at = '2026-01-05T15:00:00+05:30',
    resolution_notes = 'Asset was approved for recycling and replaced from spare inventory.'
WHERE claim_number = 'CLM-2025-0004';

INSERT INTO maintenance_tickets (
    ticket_number, asset_id, requested_by_employee_id,
    assigned_to_employee_id, vendor_id, issue, description, priority,
    status, opened_at, start_date, due_date, started_at, cost, resolution
)
SELECT seed.ticket_number, asset.id, requester.id, assignee.id, vendor.id,
       seed.issue, seed.description, seed.priority, seed.status,
       seed.opened_at, seed.start_date, seed.due_date, seed.started_at, seed.cost, seed.resolution
FROM (
    VALUES
        ('MT-2026-0001', 'AST-NET-0001', 'EMP-0002', 'EMP-0004', 'VEN-NET', 'Network switch overheating', 'The warehouse switch is reporting repeated temperature alerts.', 'HIGH', 'IN_PROGRESS', TIMESTAMPTZ '2026-08-10 09:15:00+05:30', DATE '2026-08-10', DATE '2026-08-28', TIMESTAMPTZ '2026-08-11 10:00:00+05:30', 150.00::numeric, NULL::text),
        ('MT-2026-0002', 'AST-MON-0001', 'EMP-0001', 'EMP-0004', 'VEN-TECH', 'Monitor flickering', 'Display cable and power board were inspected.', 'MEDIUM', 'COMPLETED', TIMESTAMPTZ '2026-05-01 09:15:00+05:30', DATE '2026-05-01', DATE '2026-05-10', TIMESTAMPTZ '2026-05-02 10:00:00+05:30', 75.00::numeric, 'Power board replaced and monitor returned to inventory.')
) AS seed(ticket_number, asset_tag, requester_number, assignee_number, vendor_code, issue, description, priority, status, opened_at, start_date, due_date, started_at, cost, resolution)
JOIN assets asset ON asset.asset_tag = seed.asset_tag
JOIN employees requester ON requester.employee_number = seed.requester_number
JOIN employees assignee ON assignee.employee_number = seed.assignee_number
JOIN vendors vendor ON vendor.vendor_code = seed.vendor_code
ON CONFLICT (ticket_number) DO NOTHING;

UPDATE maintenance_tickets
SET completed_at = '2026-05-04T16:00:00+05:30'
WHERE ticket_number = 'MT-2026-0002';

