-- Software licenses and assignments
-- ============================================================================

INSERT INTO software_licenses (
    software_name, vendor_id, license_type, license_key,
    seat_count, start_date, end_date, purchase_cost, status, notes
)
SELECT seed.software_name, vendor.id, seed.license_type, seed.license_key,
       seed.seat_count, seed.start_date, seed.end_date, seed.purchase_cost,
       seed.status, seed.notes
FROM (
    VALUES
        ('Microsoft 365 E3', 'VEN-TECH', 'SUBSCRIPTION', 'DEMO-M365-2026-0001', 5, DATE '2026-01-01', DATE '2026-12-31', 1200.00::numeric, 'ACTIVE', 'Annual productivity subscription.'),
        ('Adobe Creative Cloud', 'VEN-TECH', 'SUBSCRIPTION', 'DEMO-ADOBE-2026-0001', 2, DATE '2026-04-01', DATE '2027-03-31', 960.00::numeric, 'ACTIVE', 'Design team subscription.'),
        ('Microsoft Visio Standard', 'VEN-TECH', 'PERPETUAL', 'DEMO-VISIO-2024-0001', 1, DATE '2024-01-01', NULL::date, 300.00::numeric, 'ACTIVE', 'Perpetual diagramming license.'),
        ('Network Monitor Trial', 'VEN-NET', 'TRIAL', 'DEMO-NMON-2025-0001', 1, DATE '2025-07-01', DATE '2025-08-31', 0.00::numeric, 'EXPIRED', 'Expired evaluation license.')
) AS seed(software_name, vendor_code, license_type, license_key, seat_count, start_date, end_date, purchase_cost, status, notes)
JOIN vendors vendor ON vendor.vendor_code = seed.vendor_code
WHERE NOT EXISTS (
    SELECT 1
    FROM software_licenses existing
    WHERE existing.license_key = seed.license_key
);

INSERT INTO license_assignments (
    license_id, employee_id, assigned_by_user_id,
    assigned_at, revoked_at, status
)
SELECT license.id, employee.id, app_user.id,
       seed.assigned_at, seed.revoked_at, seed.status
FROM (
    VALUES
        ('DEMO-M365-2026-0001', 'EMP-0004', 'asset.admin', TIMESTAMPTZ '2026-01-05 09:00:00+05:30', NULL::timestamptz, 'ACTIVE'),
        ('DEMO-M365-2026-0001', 'EMP-0005', 'asset.admin', TIMESTAMPTZ '2026-01-05 09:15:00+05:30', NULL::timestamptz, 'ACTIVE'),
        ('DEMO-ADOBE-2026-0001', 'EMP-0001', 'asset.admin', TIMESTAMPTZ '2026-04-02 09:00:00+05:30', NULL::timestamptz, 'ACTIVE'),
        ('DEMO-VISIO-2024-0001', 'EMP-0002', 'finance.admin', TIMESTAMPTZ '2024-02-01 09:00:00+05:30', NULL::timestamptz, 'ACTIVE')
) AS seed(license_key, employee_number, username, assigned_at, revoked_at, status)
JOIN software_licenses license ON license.license_key = seed.license_key
JOIN employees employee ON employee.employee_number = seed.employee_number
JOIN app_users app_user ON app_user.username = seed.username
WHERE NOT EXISTS (
    SELECT 1
    FROM license_assignments existing
    WHERE existing.license_id = license.id
      AND existing.employee_id = employee.id
      AND existing.assigned_at = seed.assigned_at
);

-- ============================================================================
-- Notifications, audit logs, settings, and email templates
-- ============================================================================

INSERT INTO notifications (
    recipient_user_id, notification_type, priority, title, message,
    read_at, created_at
)
SELECT app_user.id, seed.notification_type, seed.priority, seed.title,
       seed.message, seed.read_at, seed.created_at
FROM (
    VALUES
        ('asset.admin', 'MAINTENANCE_DUE', 'HIGH', 'Maintenance ticket due soon', 'Ticket MT-2026-0001 is due on 2026-08-28.', NULL::timestamptz, TIMESTAMPTZ '2026-08-20 08:00:00+05:30'),
        ('asset.admin', 'ASSET_ASSIGNED', 'LOW', 'Asset assigned successfully', 'AST-LAP-0001 is assigned to David Brown.', TIMESTAMPTZ '2026-02-01 12:00:00+05:30', TIMESTAMPTZ '2026-02-01 09:05:00+05:30'),
        ('finance.admin', 'WARRANTY_EXPIRING', 'MEDIUM', 'Warranty is expiring', 'Warranty W-NET-2025-0001 expires on 2026-09-05.', NULL::timestamptz, TIMESTAMPTZ '2026-08-18 08:00:00+05:30')
) AS seed(username, notification_type, priority, title, message, read_at, created_at)
JOIN app_users app_user ON app_user.username = seed.username
WHERE NOT EXISTS (
    SELECT 1
    FROM notifications existing
    WHERE existing.recipient_user_id = app_user.id
      AND existing.title = seed.title
      AND existing.created_at = seed.created_at
);

INSERT INTO audit_logs (
    actor_user_id, entity_type, entity_id, action, old_values, new_values, created_at
)
SELECT app_user.id, seed.entity_type, seed.entity_id, seed.action,
       seed.old_values, seed.new_values, seed.created_at
FROM (
    VALUES
        ('asset.admin', 'APP_USER', (SELECT id FROM app_users WHERE username = 'asset.admin'), 'USER_CREATED', NULL::jsonb, '{"username":"asset.admin","role":"SUPER_ADMIN"}'::jsonb, TIMESTAMPTZ '2026-01-02 08:00:00+05:30'),
        ('asset.admin', 'ASSET', (SELECT id FROM assets WHERE asset_tag = 'AST-LAP-0001'), 'ASSET_CREATED', NULL::jsonb, '{"assetTag":"AST-LAP-0001","status":"ASSIGNED"}'::jsonb, TIMESTAMPTZ '2026-01-20 09:00:00+05:30'),
        ('finance.admin', 'MAINTENANCE_TICKET', (SELECT id FROM maintenance_tickets WHERE ticket_number = 'MT-2026-0001'), 'MAINTENANCE_UPDATED', '{"status":"OPEN"}'::jsonb, '{"status":"IN_PROGRESS","priority":"HIGH"}'::jsonb, TIMESTAMPTZ '2026-08-11 10:00:00+05:30')
) AS seed(username, entity_type, entity_id, action, old_values, new_values, created_at)
JOIN app_users app_user ON app_user.username = seed.username
WHERE NOT EXISTS (
    SELECT 1
    FROM audit_logs existing
    WHERE existing.actor_user_id = app_user.id
      AND existing.action = seed.action
      AND existing.created_at = seed.created_at
);

