-- ============================================================================
-- Transfers, disposals, valuations, lifecycle events, and department history
-- ============================================================================

INSERT INTO asset_transfers (
    asset_id, previous_assignment_id, new_assignment_id,
    previous_employee_id, new_employee_id, previous_location_id, new_location_id,
    requested_by_user_id, approved_by_user_id, status, reason,
    requested_at, approved_at, transferred_at, notes
)
SELECT asset.id,
       previous_assignment.id,
       new_assignment.id,
       previous_employee.id,
       new_employee.id,
       previous_location.id,
       new_location.id,
       requester.id,
       approver.id,
       'COMPLETED',
       'Temporary finance laptop transferred to operations.',
       TIMESTAMPTZ '2025-03-05 09:00:00+05:30',
       TIMESTAMPTZ '2025-03-06 09:00:00+05:30',
       TIMESTAMPTZ '2025-03-11 09:00:00+05:30',
       'Transfer completed after the operations team handover.'
FROM assets asset
JOIN assignments previous_assignment
  ON previous_assignment.asset_id = asset.id
 AND previous_assignment.assigned_at = TIMESTAMPTZ '2025-01-10 09:00:00+05:30'
JOIN assignments new_assignment
  ON new_assignment.asset_id = asset.id
 AND new_assignment.assigned_at = TIMESTAMPTZ '2025-03-11 09:00:00+05:30'
JOIN employees previous_employee ON previous_employee.employee_number = 'EMP-0005'
JOIN employees new_employee ON new_employee.employee_number = 'EMP-0003'
JOIN locations previous_location ON previous_location.code = 'HQ-2F'
JOIN locations new_location ON new_location.code = 'NORTH-WH'
JOIN app_users requester ON requester.username = 'asset.admin'
JOIN app_users approver ON approver.username = 'asset.admin'
WHERE asset.asset_tag = 'AST-LAP-0002'
  AND NOT EXISTS (
      SELECT 1
      FROM asset_transfers existing
      WHERE existing.asset_id = asset.id
        AND existing.previous_assignment_id = previous_assignment.id
  );

