INSERT INTO asset_lifecycle_events (
    asset_id, event_type, event_at, actor_user_id,
    from_status, to_status, from_location_id, to_location_id,
    assignment_id, notes, metadata
)
SELECT asset.id, seed.event_type, seed.event_at, app_user.id,
       seed.from_status, seed.to_status, from_location.id, to_location.id,
       assignment.id, seed.notes, seed.metadata
FROM (
    VALUES
        ('AST-LAP-0001', 'PURCHASED', TIMESTAMPTZ '2026-01-20 09:00:00+05:30', 'asset.admin', NULL::varchar, 'AVAILABLE', NULL::varchar, 'HQ-2F', NULL::timestamptz, 'Asset received from TechSource Lanka.', '{"source":"purchase_order","poNumber":"PO-2026-0001"}'::jsonb),
        ('AST-LAP-0001', 'ASSIGNED', TIMESTAMPTZ '2026-02-01 09:00:00+05:30', 'asset.admin', 'AVAILABLE', 'ASSIGNED', 'HQ-2F', 'HQ-2F', TIMESTAMPTZ '2026-02-01 09:00:00+05:30', 'Issued to David Brown.', '{}'::jsonb),
        ('AST-LAP-0002', 'TRANSFERRED', TIMESTAMPTZ '2025-03-11 09:00:00+05:30', 'asset.admin', 'ASSIGNED', 'AVAILABLE', 'HQ-2F', 'NORTH-WH', TIMESTAMPTZ '2025-03-11 09:00:00+05:30', 'Transferred to Operations.', '{}'::jsonb),
        ('AST-NET-0001', 'STATUS_CHANGED', TIMESTAMPTZ '2026-08-10 09:15:00+05:30', 'finance.admin', 'AVAILABLE', 'UNDER_MAINTENANCE', 'NORTH-WH', 'NORTH-WH', NULL::timestamptz, 'Maintenance ticket MT-2026-0001 opened.', '{}'::jsonb),
        ('AST-LAP-0003', 'DISPOSED', TIMESTAMPTZ '2025-12-20 15:00:00+05:30', 'asset.admin', 'RETIRED', 'DISPOSED', 'NORTH-WH', 'NORTH-WH', NULL::timestamptz, 'Asset recycled.', '{}'::jsonb),
        ('AST-NET-0002', 'PURCHASED', TIMESTAMPTZ '2026-08-05 09:00:00+05:30', 'finance.admin', NULL::varchar, 'IN_TRANSIT', NULL::varchar, 'NORTH-WH', NULL::timestamptz, 'Network equipment is in transit to the warehouse.', '{}'::jsonb)
) AS seed(asset_tag, event_type, event_at, username, from_status, to_status, from_location_code, to_location_code, assignment_at, notes, metadata)
JOIN assets asset ON asset.asset_tag = seed.asset_tag
JOIN app_users app_user ON app_user.username = seed.username
LEFT JOIN locations from_location ON from_location.code = seed.from_location_code
LEFT JOIN locations to_location ON to_location.code = seed.to_location_code
LEFT JOIN assignments assignment
  ON assignment.asset_id = asset.id
 AND assignment.assigned_at = seed.assignment_at
WHERE NOT EXISTS (
    SELECT 1
    FROM asset_lifecycle_events existing
    WHERE existing.asset_id = asset.id
      AND existing.event_type = seed.event_type
      AND existing.event_at = seed.event_at
);

INSERT INTO employee_department_history (
    employee_id, previous_department_id, new_department_id,
    changed_by_user_id, effective_from, effective_to, reason, notes
)
SELECT employee.id, previous_department.id, new_department.id,
       app_user.id, seed.effective_from, NULL, seed.reason, seed.notes
FROM (
    VALUES
        ('EMP-0001', NULL::varchar, 'IT', 'asset.admin', DATE '2021-01-11', 'Initial department assignment', 'Joined as the IT department lead.'),
        ('EMP-0002', NULL::varchar, 'FIN', 'asset.admin', DATE '2021-03-15', 'Initial department assignment', 'Joined as Finance Manager.'),
        ('EMP-0003', NULL::varchar, 'OPS', 'asset.admin', DATE '2022-02-07', 'Initial department assignment', 'Joined as Operations Manager.'),
        ('EMP-0004', NULL::varchar, 'IT', 'asset.admin', DATE '2023-06-19', 'Initial department assignment', 'Joined the technology team.'),
        ('EMP-0005', NULL::varchar, 'FIN', 'finance.admin', DATE '2024-01-08', 'Initial department assignment', 'Joined the finance team.')
) AS seed(employee_number, previous_code, new_code, username, effective_from, reason, notes)
JOIN employees employee ON employee.employee_number = seed.employee_number
LEFT JOIN departments previous_department ON previous_department.code = seed.previous_code
JOIN departments new_department ON new_department.code = seed.new_code
JOIN app_users app_user ON app_user.username = seed.username
WHERE NOT EXISTS (
    SELECT 1
    FROM employee_department_history existing
    WHERE existing.employee_id = employee.id
      AND existing.effective_from = seed.effective_from
);

